        { k: 'check', q: '$\\vec{a}=(1;\\,-2;\\,2)$ вектортой ижил чиглэлтэй коллинеар, урт нь $6$ байх вектор аль нь вэ?', o: ['$(2;\\,-4;\\,4)$', '$(-2;\\,4;\\,-4)$', '$(6;\\,-12;\\,12)$', '$(3;\\,-6;\\,6)$'], c: 0,
          why: '$|\\vec{a}|=3$ тул $\\lambda=\\dfrac{6}{3}=2$: $(2;\\,-4;\\,4)$.', hint: 'Эхлээд $|\\vec{a}|$-г ол.' },
        { k: 'sum', pts: ['Коллинеар $\\iff$ $\\vec{a}=\\lambda\\vec{b}$ $\\iff$ координатууд пропорциональ.', '$\\lambda\\gt 0$ — ижил чиглэлтэй, $\\lambda\\lt 0$ — эсрэг чиглэлтэй.',
          'Параметр олохдоо: мэдэгдэх координатуудаар $\\lambda$-г олоод, бусдыг нь гарга.', 'Гурван цэг нэг шулуун дээр $\\iff$ $\\overrightarrow{AB}$ ба $\\overrightarrow{AC}$ коллинеар.'] }
